package ec.edu.ucacue.odontocare.clinicalrecord.domain;
import java.time.LocalDateTime;import java.time.LocalDate;import ec.edu.ucacue.odontocare.treatment.domain.EvolutionResult;
import jakarta.persistence.*;
@Entity @Table(name="dental_evolutions") public class DentalEvolution{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="consultation_id")private DentalConsultation consultation;@Column(name="dental_piece_id")private Long dentalPieceId;@Column(name="procedure_id")private Long procedureId;private String description;@Enumerated(EnumType.STRING)private EvolutionResult result;@Column(name="recorded_at")private LocalDateTime recordedAt;@Column(name="next_control_date")private LocalDate nextControlDate;@Column(name="created_by")private Long createdBy;
 protected DentalEvolution(){}public DentalEvolution(DentalConsultation c,String d,Long piece,Long user){this(c,d,piece,null,EvolutionResult.STABLE,LocalDateTime.now(),null,user);}public DentalEvolution(DentalConsultation c,String d,Long piece,Long procedure,EvolutionResult result,LocalDateTime date,LocalDate next,Long user){consultation=c;description=d;dentalPieceId=piece;procedureId=procedure;this.result=result;recordedAt=date;nextControlDate=next;createdBy=user;}public Long getId(){return id;}public String getDescription(){return description;}public Long getDentalPieceId(){return dentalPieceId;}public Long getProcedureId(){return procedureId;}public EvolutionResult getResult(){return result;}public LocalDateTime getRecordedAt(){return recordedAt;}public LocalDate getNextControlDate(){return nextControlDate;}public DentalConsultation getConsultation(){return consultation;}
}
